  subject {
    common_name = "example-bucket.example.internal"
  }

  dns_names             = ["example-bucket.example.internal"]
  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

# First bucket - establishes the shared bucket server.
