  name      = "example-bucket-first"
  volume_id = azurerm_netapp_volume.example.id

  file_system_nfs_user {
    group_id = 1000
    user_id  = 1000
  }

  server {
    fqdn            = "example-bucket.example.internal"
    certificate_pem = base64encode("${tls_self_signed_cert.bucket.cert_pem}${tls_private_key.bucket.private_key_pem}")
  }
}

# Subsequent bucket - reuses the server configured by the first bucket.
resource "azurerm_netapp_volume_bucket" "example" {
  name      = "example-bucket-second"
  volume_id = azurerm_netapp_volume.example.id

  file_system_nfs_user {
    group_id = 2000
    user_id  = 2000
  }

  depends_on = [azurerm_netapp_volume_bucket_with_server.first]
